INSERT INTO "tc_products" ("id", "data") VALUES
  ('bel-oil', $belnco${"id":"bel-oil","name":"Centella Cleansing Oil","short":"Cleansing Oil","category":"Nettoyant","price":1700,"image":"/assets/products/bel-oil.webp","source":"https://belnco.com/products/centella-cleansing-oil-1","description":"Huile démaquillante à la centella et au ginseng : la première étape du nettoyage, sur peau sèche. Elle dissout maquillage, crème solaire et sébum sans dessécher.","concerns":["red","dull","oil","dry"],"skins":["oily","mixed","normal","dry"],"active":false,"size":"250 ml","enabled":false,"recommendable":true,"review":"draft","priceSource":"Prix du site belnco.com, consulté le 20/11/2026","domain":"face","components":[],"ingredients":[{"name":"Centella asiatica","inci":"Centella Asiatica Extract","role":"Apaise les rougeurs et les irritations."},{"name":"Huiles de jojoba et de tournesol","inci":"Simmondsia Chinensis Seed Oil, Helianthus Annuus Seed Oil","role":"Dissolvent le maquillage waterproof et la crème solaire sans frotter."},{"name":"Ginseng","inci":"Panax Ginseng Root Extract","role":"Éclat et protection antioxydante."}],"pitch":"La première étape du double nettoyage : sur peau sèche, l’huile retire maquillage, crème solaire et sébum sans décaper ni frotter, puis devient laiteuse au contact de l’eau.","usage":"Sur peau sèche, 2 à 3 pressions. Masser en petits cercles, ajouter un peu d’eau pour émulsionner, puis rincer à l’eau tiède. Usage quotidien.","cautions":["Contient du parfum.","Ne contient pas de rétinol : la page du site affiche par erreur les textes du sérum rétinol.","Tolérance individuelle à vérifier. Pas de résultat garanti."],"checkedAt":"2026-11-20","formulaNote":"Formule complète non reprise : plusieurs pages du site affichent la formule d’un autre produit. Le flacon du lot fait foi ; rôles des ingrédients, pas preuve d’un résultat.","fragrance":true,"gentle":false,"exfoliant":false,"brand":"belnco"}$belnco$::jsonb),
  ('bel-gel', $belnco${"id":"bel-gel","name":"Centella Cleansing Gel","short":"Cleansing Gel","category":"Nettoyant","price":1700,"image":"/assets/products/bel-gel.webp","source":"https://belnco.com/products/centella-cleansing-gel-2","description":"Gel nettoyant à la centella, à la niacinamide et à l’acide salicylique, pour peaux sensibles, mixtes ou à imperfections, matin et soir.","concerns":["red","dehydration","acne","marks"],"skins":["oily","mixed","normal","dry"],"active":false,"size":"250 ml","enabled":false,"recommendable":true,"review":"draft","priceSource":"Prix du site belnco.com, consulté le 20/11/2026","domain":"face","components":[],"ingredients":[{"name":"Centella asiatica","inci":"Centella Asiatica Extract","role":"Apaise et renforce la barrière cutanée."},{"name":"Niacinamide","inci":"Niacinamide","role":"Unifie le teint et atténue l’apparence des imperfections."},{"name":"Acide salicylique","inci":"Salicylic Acid","role":"Aide à désobstruer ; dose non indiquée."}],"pitch":"Le nettoyant du matin et du soir : il nettoie sans décaper, apaise la peau réactive et aide à unifier le teint. Après l’huile, il complète le double nettoyage.","usage":"Sur peau mouillée, une petite quantité. Masser en petits cercles, puis rincer à l’eau tiède. Matin et soir.","cautions":["Contient de l’acide salicylique (dose non indiquée) et du parfum.","Sur peau sensible, introduire progressivement un sérum aux acides à côté de ce gel.","Ne contient pas de rétinol : la page du site affiche par erreur les textes du sérum rétinol.","Tolérance individuelle à vérifier. Pas de résultat garanti."],"checkedAt":"2026-11-20","formulaNote":"Formule complète non reprise : plusieurs pages du site affichent la formule d’un autre produit. Le flacon du lot fait foi ; rôles des ingrédients, pas preuve d’un résultat.","fragrance":true,"gentle":false,"exfoliant":true,"brand":"belnco"}$belnco$::jsonb),
  ('bel-spf30', $belnco${"id":"bel-spf30","name":"CENTELLA SERUM SPF 30","short":"Centella Serum SPF 30","category":"Soin ciblé","price":1800,"image":"/assets/products/bel-spf30.webp","source":"https://belnco.com/products/centella-serum-spf-30","description":"Sérum de jour à la centella avec SPF 30 intégré : il apaise rougeurs et irritations, renforce la barrière et protège des UVA et des UVB.","concerns":["red","dehydration","aging"],"skins":["oily","mixed","normal","dry"],"active":false,"size":"30 ml","enabled":false,"recommendable":true,"review":"draft","priceSource":"Prix du site belnco.com, consulté le 20/11/2026","domain":"face","components":[],"ingredients":[{"name":"Centella asiatica","inci":"Centella Asiatica Extract","role":"Apaise, répare et renforce la barrière cutanée."},{"name":"Eau florale de camomille","inci":"Chamomilla Recutita (Matricaria) Flower Water","role":"Calme les rougeurs et maintient l’hydratation."},{"name":"Oxyde de zinc","inci":"Zinc Oxide","role":"Cité dans la formule ; son rôle n’est pas précisé par la marque."}],"pitch":"Le soin du matin d’une peau sensible : il apaise et protège en un seul geste, en dernière étape avant le maquillage. C’est aussi le soin du lendemain matin après un actif du soir.","usage":"Chaque matin, sur peau propre et sèche, 2 à 3 pressions sur le visage, le cou et le décolleté, en évitant les yeux. Dernière étape avant le maquillage. Au soleil, réappliquer toutes les 2 à 3 heures.","cautions":["Matin uniquement.","SPF 30 : réappliquer toutes les 2 à 3 heures au soleil, après la baignade ou une forte transpiration.","Éviter la zone des yeux.","Les chiffres affichés sur le site viennent d’un test consommateurs, pas d’une étude clinique.","Tolérance individuelle à vérifier. Pas de résultat garanti."],"checkedAt":"2026-11-20","formulaNote":"Formule complète non reprise : plusieurs pages du site affichent la formule d’un autre produit. Le flacon du lot fait foi ; rôles des ingrédients, pas preuve d’un résultat.","g